with up as (update public.artists a set bio=x.b from json_to_recordset('[{"s":"og-shez","b":"OG SHEZ is a Mumbai DJ who plays independent Desi hip-hop, Jersey club, dubstep, electro and experimental edits. She runs the party series Culture Club, whose second edition was set for Raasta Mumbai on 22 May 2026."},{"s":"tech-panda-x-kenzani","b":"Tech Panda & Kenzani are a New Delhi DJ-producer duo who blend Indian vocal samples and traditional music with techno and downtempo."},{"s":"ashna","b":"Ashna Malik is a New Delhi-based DJ and artist who plays disco, house and electronic music. She returned to India in 2021 to start her creative career there."}]'::json) as x(s text,b text) where a.slug=x.s and (a.bio is null or length(trim(a.bio))<20) returning 1) select count(*) from up;